#include <bits/stdc++.h>
using namespace std;
int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int m,n;if(!(cin>>m>>n)) return 0;vector<int> seq(m*n);for(int&i:seq)cin>>i;vector<vector<int>> mach(n+1,vector<int>(m)), dur(n+1,vector<int>(m));for(int j=1;j<=n;j++)for(int k=0;k<m;k++)cin>>mach[j][k];for(int j=1;j<=n;j++)for(int k=0;k<m;k++)cin>>dur[j][k];vector<vector<pair<int,int>>> sch(m+1);vector<int> cnt(n+1), jobEnd(n+1);int ans=0;for(int j:seq){int k=cnt[j]++, mc=mach[j][k], d=dur[j][k];auto &v=sch[mc];int cur=jobEnd[j], start=cur, pos=v.size();for(int i=0;i<(int)v.size();i++){int s=v[i].first,e=v[i].second;if(cur+d<=s){start=cur;pos=i;break;}if(cur<e)cur=e;}if(pos==(int)v.size())start=cur;v.insert(v.begin()+pos,{start,start+d});jobEnd[j]=start+d;ans=max(ans,jobEnd[j]);}cout<<ans<<"\n";}
